import { useReducer } from "react";
import reducer, { initialState } from "./reducer";
import { DEVELOPER, NUMBER, AGE } from "./actionTypes";

import "./App.css";
import { Form } from "formik";

function App() {
  const [state, dispatch] = useReducer(reducer, initialState);

  function developer() {
    dispatch({ type: DEVELOPER });
  }


  function test(e) {
    e.preventDefault();
    const { input } = e.target;
    console.log(input.value);
    number ()
    // dispatch({ type: AGE, payload: values.username });
    input.value = "";
  }

  function number() {
    dispatch({ type: NUMBER, payload: input.value });
  }

  return (
    <div className="appContainer">
      <div className="mainApp">
        <div>
          <form className="buttons" onSubmit={test}>
            <div className="fieldDiv">
              <p className="fieldP">Enter Username</p>
              <input className="field" id="input" />
            </div>
            <button className="fieldBtn" type="button" onClick={developer}>
              ADD DEVELOPER
            </button>
            <button className="fieldBtn" type="button" onClick={test}>
              SHUFFLE ARRAY
            </button>
            <button className="fieldBtn" type="button" onClick={number}>
              ADD NUMBER
            </button>
            <button className="fieldBtn" type="button">
              REMOVE SINGLE DIGITS
            </button>
            <button className="fieldBtn" type="submit">
              CHANGE USER
            </button>
            <button className="fieldBtn" type="submit">
              ADD AGE
            </button>
          </form>
        </div>
        <div className="output">
          <p>Output</p>
          <p>{JSON.stringify(state)}</p>
        </div>
      </div>
    </div>
  );
}

export default App;
